domain F32 {
function fromInt(i: Int): F32
function fromReal(r: Real): F32
function add(a: F32, b: F32): F32
function sub(a: F32, b: F32): F32
function mul(a: F32, b: F32): F32
function div(a: F32, b: F32): F32
function sqrt(a: F32): F32
function clamp(x: F32, lo: F32, hi: F32): F32
function lt(a: F32, b: F32): Bool
function le(a: F32, b: F32): Bool
function isNan(a: F32): Bool
function isInf(a: F32): Bool
function negInf(): F32
function posInf(): F32
function zero(): F32
function one(): F32
function minusOne(): F32
function hundred(): F32
function approxEqAbs(a: F32, b: F32, eps: F32): Bool
axiom !isNan(zero())
axiom !isNan(one())
axiom !isNan(minusOne())
axiom !isNan(hundred())
axiom !isInf(zero())
axiom !isInf(one())
axiom !isInf(minusOne())
axiom !isInf(hundred())
axiom forall x: F32, lo: F32, hi: F32 :: !isNan(x) && !isNan(lo) && !isNan(hi) && lt(lo, hi) ==> le(lo, clamp(x, lo, hi)) && le(clamp(x, lo, hi), hi)
axiom forall x: F32 :: !isNan(x) ==> le(clamp(x, zero(), hundred()), hundred())
axiom forall x: F32 :: !isNan(x) ==> le(zero(), clamp(x, zero(), hundred()))
axiom forall x: F32 :: !isNan(x) ==> le(clamp(x, zero(), one()), one())
axiom forall x: F32 :: !isNan(x) ==> le(zero(), clamp(x, zero(), one()))
axiom forall x: F32 :: !isNan(x) ==> le(clamp(x, minusOne(), one()), one())
axiom forall x: F32 :: !isNan(x) ==> le(minusOne(), clamp(x, minusOne(), one()))
axiom forall a: F32, b: F32, c: F32 :: lt(a, b) && lt(b, c) ==> lt(a, c)
axiom forall a: F32, b: F32 :: lt(a, b) ==> le(a, b)
axiom forall a: F32 :: le(a, a)
}

domain U64 {
function max(): Int
function min(): Int
function addWrap(a: Int, b: Int): Int
function mulWrap(a: Int, b: Int): Int
function xor(a: Int, b: Int): Int
function lt(a: Int, b: Int): Bool
function le(a: Int, b: Int): Bool
function subAbs(a: Int, b: Int): Int
function min2(a: Int, b: Int): Int
function max2(a: Int, b: Int): Int
function popCount(a: Int): Int
axiom min() == 0
axiom max() == 18446744073709551615
axiom forall x: Int :: le(min(), x) && le(x, max()) ==> le(min(), addWrap(x, 0)) && le(addWrap(x, 0), max())
axiom forall x: Int :: le(min(), x) && le(x, max()) ==> le(min(), mulWrap(x, 1)) && le(mulWrap(x, 1), max())
axiom forall a: Int, b: Int :: le(min(), a) && le(a, max()) && le(min(), b) && le(b, max()) ==> le(min(), addWrap(a, b)) && le(addWrap(a, b), max())
axiom forall a: Int, b: Int :: le(min(), a) && le(a, max()) && le(min(), b) && le(b, max()) ==> le(min(), mulWrap(a, b)) && le(mulWrap(a, b), max())
axiom forall a: Int, b: Int :: le(min(), a) && le(a, max()) && le(min(), b) && le(b, max()) ==> le(min(), xor(a, b)) && le(xor(a, b), max())
axiom forall a: Int, b: Int :: le(min(), a) && le(a, max()) && le(min(), b) && le(b, max()) ==> le(min(), subAbs(a, b)) && le(subAbs(a, b), max())
axiom forall a: Int, b: Int :: le(min(), a) && le(a, max()) && le(min(), b) && le(b, max()) ==> le(min(), min2(a, b)) && le(min2(a, b), max())
axiom forall a: Int, b: Int :: le(min(), a) && le(a, max()) && le(min(), b) && le(b, max()) ==> le(min(), max2(a, b)) && le(max2(a, b), max())
axiom forall x: Int :: le(min(), x) && le(x, max()) ==> popCount(x) >= 0
}

function minInt(a: Int, b: Int): Int { if a < b then a else b }
function maxInt(a: Int, b: Int): Int { if a < b then b else a }

function RankerConfig_STREAMING_BUFFER_SIZE(): Int { 1024 }
function RankerConfig_STREAMING_WINDOW_SIZE(): Int { 512 }
function RankerConfig_DEFAULT_TOP_K_RETRIEVAL(): Int { 1000 }
function RankerConfig_HASH_SEED_MULTIPLIER_A(): Int { 11400714819323198485 }
function RankerConfig_HASH_SEED_MULTIPLIER_B(): Int { 5871781006564002453 }

function RankerConfig_LEARNING_RATE(): F32 { F32.fromReal(0.01) }
function RankerConfig_DIVERSITY_WEIGHT(): F32 { F32.fromReal(0.3) }
function RankerConfig_PROXIMITY_WEIGHT(): F32 { F32.fromReal(0.3) }
function RankerConfig_MAX_RAW_SCORE(): F32 { F32.hundred() }
function RankerConfig_BASE_SCORE_WEIGHT(): F32 { F32.fromReal(0.4) }
function RankerConfig_OVERLAP_WEIGHT(): F32 { F32.fromReal(0.3) }
function RankerConfig_JACCARD_WEIGHT(): F32 { F32.fromReal(0.3) }

function bytesOfU32Seq(s: Seq[Int]): Seq[Int]
function stableHash(bytes: Seq[Int], seed: Int): Int

function distinctCountU32(s: Seq[Int]): Int
axiom forall s: Seq[Int] :: 0 <= distinctCountU32(s) && distinctCountU32(s) <= |s|

function memEqlSeqInt(a: Seq[Int], b: Seq[Int]): Bool
axiom forall a: Seq[Int], b: Seq[Int] :: memEqlSeqInt(a, b) <==> (|a| == |b| && forall i: Int :: 0 <= i && i < |a| ==> a[i] == b[i])

field len: Int
field u32Data: Seq[Int]
field u64Data: Seq[Int]
field usizeData: Seq[Int]
field f32Data: Seq[F32]
field boolData: Seq[Bool]
field refData: Seq[Ref]

field ranker_ngram_weights: Ref
field ranker_lsh_hash_params: Ref
field ranker_num_hash_functions: Int
field ranker_num_ngrams: Int
field ranker_seed: Int
field ranker_allocator: Ref

field segment_score: F32
field segment_anchor_hash: Int
field segment_position: Int

field ranked_tokens: Ref
field ranked_score: F32
field ranked_position: Int
field ranked_anchor: Bool

field tensor_shape: Ref
field tensor_data: Ref

field bitset_bits: Ref

predicate Allocator(a: Ref)

predicate ArrayU32(a: Ref) {
acc(a.len) && acc(a.u32Data) && a.len == |a.u32Data|
}

predicate ArrayU32Read(a: Ref) {
acc(a.len, 1/2) && acc(a.u32Data, 1/2) && a.len == |a.u32Data|
}

predicate ArrayU64(a: Ref) {
acc(a.len) && acc(a.u64Data) && a.len == |a.u64Data|
}

predicate ArrayU64Read(a: Ref) {
acc(a.len, 1/2) && acc(a.u64Data, 1/2) && a.len == |a.u64Data|
}

predicate ArrayUSize(a: Ref) {
acc(a.len) && acc(a.usizeData) && a.len == |a.usizeData|
}

predicate ArrayUSizeRead(a: Ref) {
acc(a.len, 1/2) && acc(a.usizeData, 1/2) && a.len == |a.usizeData|
}

predicate ArrayF32(a: Ref) {
acc(a.len) && acc(a.f32Data) && a.len == |a.f32Data|
}

predicate ArrayF32Read(a: Ref) {
acc(a.len, 1/2) && acc(a.f32Data, 1/2) && a.len == |a.f32Data|
}

predicate ArrayBool(a: Ref) {
acc(a.len) && acc(a.boolData) && a.len == |a.boolData|
}

predicate ArrayBoolRead(a: Ref) {
acc(a.len, 1/2) && acc(a.boolData, 1/2) && a.len == |a.boolData|
}

predicate ArrayRef(a: Ref) {
acc(a.len) && acc(a.refData) && a.len == |a.refData|
}

predicate ArrayRefRead(a: Ref) {
acc(a.len, 1/2) && acc(a.refData, 1/2) && a.len == |a.refData|
}

predicate Segment(s: Ref) {
acc(s.segment_score, 1/2) && acc(s.segment_anchor_hash, 1/2) && acc(s.segment_position, 1/2)
}

predicate SegmentWrite(s: Ref) {
acc(s.segment_score) && acc(s.segment_anchor_hash) && acc(s.segment_position)
}

predicate RankedSegment(r: Ref) {
acc(r.ranked_tokens) && acc(r.ranked_score) && acc(r.ranked_position) && acc(r.ranked_anchor) &&
ArrayU32(r.ranked_tokens)
}

predicate RankedSegmentRead(r: Ref) {
acc(r.ranked_tokens, 1/2) && acc(r.ranked_score, 1/2) && acc(r.ranked_position, 1/2) && acc(r.ranked_anchor, 1/2) &&
ArrayU32Read(r.ranked_tokens)
}

predicate Tensor(t: Ref) {
acc(t.tensor_shape, 1/2) && acc(t.tensor_data, 1/2) &&
ArrayUSizeRead(t.tensor_shape) &&
ArrayF32Read(t.tensor_data)
}

predicate TensorWrite(t: Ref) {
acc(t.tensor_shape) && acc(t.tensor_data) &&
ArrayUSize(t.tensor_shape) &&
ArrayF32(t.tensor_data)
}

predicate BitSet(b: Ref) {
acc(b.bitset_bits, 1/2) && ArrayU64Read(b.bitset_bits)
}

predicate SSI(ssi: Ref)

predicate Ranker(r: Ref) {
acc(r.ranker_ngram_weights) &&
acc(r.ranker_lsh_hash_params) &&
acc(r.ranker_num_hash_functions) &&
acc(r.ranker_num_ngrams) &&
acc(r.ranker_seed) &&
acc(r.ranker_allocator) &&
Allocator(r.ranker_allocator) &&
ArrayF32(r.ranker_ngram_weights) &&
ArrayU64(r.ranker_lsh_hash_params) &&
r.ranker_num_ngrams == r.ranker_ngram_weights.len &&
r.ranker_lsh_hash_params.len == r.ranker_num_hash_functions * 2 &&
r.ranker_num_hash_functions >= 0 &&
r.ranker_num_ngrams >= 0
}

method allocU32(a: Ref, n: Int) returns (arr: Ref)
requires Allocator(a)
requires n >= 0
ensures ArrayU32(arr)
{
arr := new()
inhale acc(arr.len) && acc(arr.u32Data)
var d: Seq[Int]
inhale |d| == n
arr.len := n
arr.u32Data := d
fold ArrayU32(arr)
}

