requires Allocator(a)
requires ArrayU64(arr)
ensures true
{
unfold ArrayU64(arr)
exhale acc(arr.len) && acc(arr.u64Data)
}

method freeUSize(a: Ref, arr: Ref)
requires Allocator(a)
requires ArrayUSize(arr)
ensures true
{
unfold ArrayUSize(arr)
exhale acc(arr.len) && acc(arr.usizeData)
}

