method freeRef(a: Ref, arr: Ref)
requires Allocator(a)
requires ArrayRef(arr)
ensures true
{
unfold ArrayRef(arr)
exhale acc(arr.len) && acc(arr.refData)
}

method dupeU32(a: Ref, src: Ref) returns (dst: Ref)
requires Allocator(a)
requires ArrayU32Read(src)
ensures ArrayU32(dst)
ensures dst.u32Data == src.u32Data
{
unfold ArrayU32Read(src)
call dst := allocU32(a, src.len)
unfold ArrayU32(dst)
dst.u32Data := src.u32Data
fold ArrayU32(dst)
fold ArrayU32Read(src)
}

method dupeF32(a: Ref, src: Ref) returns (dst: Ref)
requires Allocator(a)
requires ArrayF32Read(src)
ensures ArrayF32(dst)
ensures dst.f32Data == src.f32Data
{
unfold ArrayF32Read(src)
call dst := allocF32(a, src.len)
unfold ArrayF32(dst)
dst.f32Data := src.f32Data
fold ArrayF32(dst)
fold ArrayF32Read(src)
}

method SSI_getSegment(ssi: Ref, key: Int) returns (seg: Ref, found: Bool)
requires SSI(ssi)
ensures found ==> Segment(seg)
{
seg := new()
inhale acc(seg.segment_score, 1/2) && acc(seg.segment_anchor_hash, 1/2) && acc(seg.segment_position, 1/2)
inhale Segment(seg)
}

method SSI_retrieveTopK(ssi: Ref, queryTokens: Ref, k: Int, a: Ref) returns (arr: Ref)
requires SSI(ssi)
requires Allocator(a)
requires ArrayU32Read(queryTokens)
requires k >= 0
ensures ArrayRef(arr)
ensures forall i: Int :: 0 <= i && i < arr.len ==> RankedSegment(arr.refData[i])
{
call arr := allocRef(a, k)
unfold ArrayRef(arr)
var i: Int := 0
while (i < arr.len)
invariant 0 <= i && i <= arr.len
invariant acc(arr.len) && acc(arr.refData)
{
var rs: Ref := new()
inhale acc(rs.ranked_tokens) && acc(rs.ranked_score) && acc(rs.ranked_position) && acc(rs.ranked_anchor)
call rsToks := allocU32(a, 0)
rs.ranked_tokens := rsToks
rs.ranked_score := F32.zero()
rs.ranked_position := 0
rs.ranked_anchor := false
fold ArrayU32(rsToks)
fold RankedSegment(rs)
arr.refData := arr.refData[i := rs]
i := i + 1
}
fold ArrayRef(arr)
}

method RankedSegment_init(a: Ref, tokens: Ref, score: F32, position: Int, anchor: Bool) returns (rs: Ref)
requires Allocator(a)
requires ArrayU32Read(tokens)
ensures RankedSegment(rs)
{
rs := new()
inhale acc(rs.ranked_tokens) && acc(rs.ranked_score) && acc(rs.ranked_position) && acc(rs.ranked_anchor)
call dup := dupeU32(a, tokens)
rs.ranked_tokens := dup
rs.ranked_score := score
rs.ranked_position := position
rs.ranked_anchor := anchor
fold RankedSegment(rs)
}

method RankedSegment_deinit(a: Ref, rs: Ref)
requires Allocator(a)
requires RankedSegment(rs)
ensures true
{
unfold RankedSegment(rs)
call freeU32(a, rs.ranked_tokens)
exhale acc(rs.ranked_tokens) && acc(rs.ranked_score) && acc(rs.ranked_position) && acc(rs.ranked_anchor)
}

method Ranker_init(allocator: Ref, num_ngrams: Int, num_hash_funcs: Int, seed: Int) returns (res: Ref)
requires Allocator(allocator)
requires num_ngrams > 0
requires num_hash_funcs > 0
ensures Ranker(res)
{
var weights: Ref
call weights := allocF32(allocator, num_ngrams)
unfold ArrayF32(weights)
var i: Int := 0
while (i < weights.len)
invariant 0 <= i && i <= weights.len
invariant acc(weights.len) && acc(weights.f32Data)
invariant weights.len == num_ngrams
{
var denom: F32 := F32.fromInt(i + 1)
var decay: F32 := F32.div(F32.one(), denom)
weights.f32Data := weights.f32Data[i := decay]
i := i + 1
}
fold ArrayF32(weights)

var hash_params: Ref
call hash_params := allocU64(allocator, num_hash_funcs * 2)
unfold ArrayU64(hash_params)
i := 0
while (i < num_hash_funcs)
invariant 0 <= i && i <= num_hash_funcs
invariant acc(hash_params.len) && acc(hash_params.u64Data)
invariant hash_params.len == num_hash_funcs * 2
{
var i_u64: Int := i
var i_plus_one: Int := i + 1
var v0: Int := U64.addWrap(seed, U64.mulWrap(i_u64, RankerConfig_HASH_SEED_MULTIPLIER_A()))
var v1: Int := U64.addWrap(seed, U64.mulWrap(i_plus_one, RankerConfig_HASH_SEED_MULTIPLIER_B()))
hash_params.u64Data := hash_params.u64Data[(i * 2) := v0]
hash_params.u64Data := hash_params.u64Data[(i * 2 + 1) := v1]
i := i + 1
}
fold ArrayU64(hash_params)

res := new()
inhale acc(res.ranker_ngram_weights) && acc(res.ranker_lsh_hash_params) && acc(res.ranker_num_hash_functions) && acc(res.ranker_num_ngrams) && acc(res.ranker_seed) && acc(res.ranker_allocator)
res.ranker_ngram_weights := weights
res.ranker_lsh_hash_params := hash_params
res.ranker_num_hash_functions := num_hash_funcs
res.ranker_num_ngrams := num_ngrams
res.ranker_seed := seed
res.ranker_allocator := allocator
fold Ranker(res)
}

method Ranker_deinit(self: Ref)
requires Ranker(self)
ensures true
{
unfold Ranker(self)
call freeF32(self.ranker_allocator, self.ranker_ngram_weights)
call freeU64(self.ranker_allocator, self.ranker_lsh_hash_params)
exhale acc(self.ranker_ngram_weights) && acc(self.ranker_lsh_hash_params) && acc(self.ranker_num_hash_functions) && acc(self.ranker_num_ngrams) && acc(self.ranker_seed) && acc(self.ranker_allocator)
}

method Ranker_computeTokenDiversity(self: Ref, tokens: Ref) returns (div: F32)
requires Ranker(self)
requires ArrayU32Read(tokens)
ensures true
{
unfold ArrayU32Read(tokens)
if (tokens.len == 0) {
div := F32.zero()
} else {
var u: Int := distinctCountU32(tokens.u32Data)
var num: F32 := F32.fromInt(u)
var den: F32 := F32.fromInt(tokens.len)
div := F32.div(num, den)
}
fold ArrayU32Read(tokens)
}

method Ranker_computeTokenOverlap(self: Ref, tokens: Ref, query: Ref) returns (ov: F32)
requires Ranker(self)
requires ArrayU32Read(tokens)
requires ArrayU32Read(query)
ensures true
{
unfold ArrayU32Read(tokens)
unfold ArrayU32Read(query)
if (tokens.len == 0 || query.len == 0) {
ov := F32.zero()
} else {
var overlap: Int := 0
var i: Int := 0
while (i < tokens.len)
invariant 0 <= i && i <= tokens.len
invariant overlap >= 0
{
var token: Int := tokens.u32Data[i]
var found: Bool := false
var j: Int := 0
while (j < query.len)
invariant 0 <= j && j <= query.len
{
if (!found && token == query.u32Data[j]) {
found := true
}
j := j + 1
}
if (found) {
overlap := overlap + 1
}
i := i + 1
}
var max_len: Int := maxInt(tokens.len, query.len)
var num: F32 := F32.fromInt(overlap)
var den: F32 := F32.fromInt(max_len)
ov := F32.div(num, den)
}
fold ArrayU32Read(query)
fold ArrayU32Read(tokens)
}

method Ranker_computeJaccardSimilarity(self: Ref, tokens: Ref, query: Ref) returns (jac: F32)
requires Ranker(self)
requires ArrayU32Read(tokens)
requires ArrayU32Read(query)
ensures true
{
unfold ArrayU32Read(tokens)
unfold ArrayU32Read(query)
if (tokens.len == 0 && query.len == 0) {
jac := F32.one()
} else if (tokens.len == 0 || query.len == 0) {
jac := F32.zero()
} else {
var inter: Int := 0
var uni: Int := 0
var seenT: Set[Int] := {}
var i: Int := 0
while (i < tokens.len)
invariant 0 <= i && i <= tokens.len
invariant seenT subseteq set(tokens.u32Data[0..i])
{
seenT := seenT union {tokens.u32Data[i]}
i := i + 1
}
var seenQ: Set[Int] := {}
var j: Int := 0
while (j < query.len)
invariant 0 <= j && j <= query.len
invariant seenQ subseteq set(query.u32Data[0..j])
{
seenQ := seenQ union {query.u32Data[j]}
j := j + 1
}
var uSet: Set[Int] := seenT union seenQ
var iSet: Set[Int] := seenT intersect seenQ
uni := |uSet|
inter := |iSet|
if (uni == 0) {
jac := F32.zero()
} else {
jac := F32.div(F32.fromInt(inter), F32.fromInt(uni))
}
}
fold ArrayU32Read(query)
fold ArrayU32Read(tokens)
}

method Ranker_anchorProximity(self: Ref, tokens: Ref, ssi: Ref) returns (prox: F32)
requires Ranker(self)
requires ArrayU32Read(tokens)
requires SSI(ssi)
ensures true
{
unfold ArrayU32Read(tokens)
if (tokens.len == 0) {
prox := F32.zero()
} else {
var anchors: Int := 0
var total_dist: F32 := F32.zero()
var i: Int := 0
while (i < tokens.len)
invariant 0 <= i && i <= tokens.len
invariant anchors >= 0
{
var seg: Ref
var found: Bool
call (seg, found) := SSI_getSegment(ssi, i)
if (found) {
unfold Segment(seg)
if (seg.segment_anchor_hash != 0) {
anchors := anchors + 1
var distU: Int := U64.subAbs(i, seg.segment_position)
var clamped: Int := U64.min2(distU, 4294967295)
var distF: F32 := F32.fromInt(clamped)
total_dist := F32.add(total_dist, distF)
}
fold Segment(seg)
}
i := i + 1
}
if (anchors == 0) {
prox := F32.zero()
} else {
var denomU: Int := U64.mulWrap(anchors, tokens.len)
var denomC: Int := U64.min2(denomU, 4294967295)
var denomNZ: Int := maxInt(denomC, 1)
var denomF: F32 := F32.fromInt(denomNZ)
var frac: F32 := F32.div(total_dist, denomF)
var cl: F32 := F32.clamp(frac, F32.zero(), F32.one())
prox := F32.sub(F32.one(), cl)
}
}
fold ArrayU32Read(tokens)
}

method Ranker_scoreSequence(self: Ref, tokens: Ref, ssi: Ref) returns (score: F32)
requires Ranker(self)
requires ArrayU32Read(tokens)
requires SSI(ssi)
ensures true
{
unfold Ranker(self)
unfold ArrayU32Read(tokens)
unfold ArrayF32(self.ranker_ngram_weights)
if (tokens.len == 0) {
score := F32.zero()
} else {
var ngram_score: F32 := F32.zero()
var gram: Int := 1
var gramLimit: Int := minInt(self.ranker_num_ngrams, tokens.len + 1)
while (gram < gramLimit)
invariant 1 <= gram && gram <= gramLimit
invariant gramLimit == minInt(self.ranker_num_ngrams, tokens.len + 1)
invariant tokens.len >= 0
{
if (tokens.len >= gram) {
var start: Int := 0
var startLimit: Int := tokens.len - gram + 1
while (start < startLimit)
invariant 0 <= start && start <= startLimit
invariant startLimit == tokens.len - gram + 1
{
var ngram: Seq[Int] := tokens.u32Data[start .. start + gram]
var h: Int := stableHash(bytesOfU32Seq(ngram), self.ranker_seed)
var seg: Ref
var found: Bool
call (seg, found) := SSI_getSegment(ssi, h)
if (found) {
unfold Segment(seg)
var weight_idx: Int := minInt(gram - 1, self.ranker_ngram_weights.len - 1)
var w: F32 := self.ranker_ngram_weights.f32Data[weight_idx]
var prod: F32 := F32.mul(w, seg.segment_score)
ngram_score := F32.add(ngram_score, prod)
fold Segment(seg)
}
start := start + 1
}
}
gram := gram + 1
}

var diversity: F32
call diversity := Ranker_computeTokenDiversity(self, tokens)
var proximity: F32
call proximity := Ranker_anchorProximity(self, tokens, ssi)
var wDiv: F32 := F32.mul(RankerConfig_DIVERSITY_WEIGHT(), diversity)
var wProx: F32 := F32.mul(RankerConfig_PROXIMITY_WEIGHT(), proximity)
var raw: F32 := F32.add(ngram_score, F32.add(wDiv, wProx))
raw := F32.clamp(raw, F32.zero(), RankerConfig_MAX_RAW_SCORE())
score := F32.div(raw, RankerConfig_MAX_RAW_SCORE())

}
fold ArrayF32(self.ranker_ngram_weights)
fold ArrayU32Read(tokens)
fold Ranker(self)
}

method Ranker_scoreSequenceWithQuery(self: Ref, tokens: Ref, query: Ref, ssi: Ref) returns (score: F32)
requires Ranker(self)
requires ArrayU32Read(tokens)
requires ArrayU32Read(query)
requires SSI(ssi)
ensures true
{
var base: F32
call base := Ranker_scoreSequence(self, tokens, ssi)
var overlap: F32
call overlap := Ranker_computeTokenOverlap(self, tokens, query)
var jac: F32
call jac := Ranker_computeJaccardSimilarity(self, tokens, query)
var part1: F32 := F32.mul(base, RankerConfig_BASE_SCORE_WEIGHT())
var part2: F32 := F32.mul(overlap, RankerConfig_OVERLAP_WEIGHT())
var part3: F32 := F32.mul(jac, RankerConfig_JACCARD_WEIGHT())
var comb: F32 := F32.add(part1, F32.add(part2, part3))
score := F32.clamp(comb, F32.zero(), F32.one())
}

method Ranker_minHashSignature(self: Ref, tokens: Ref) returns (sig: Ref)
requires Ranker(self)
requires ArrayU32Read(tokens)
ensures ArrayU64(sig)
ensures sig.len == self.ranker_num_hash_functions
{
unfold Ranker(self)
unfold ArrayU32Read(tokens)
unfold ArrayU64(self.ranker_lsh_hash_params)
call sig := allocU64(self.ranker_allocator, self.ranker_num_hash_functions)
unfold ArrayU64(sig)
if (tokens.len == 0) {
var h0: Int := 0
while (h0 < sig.len)
invariant 0 <= h0 && h0 <= sig.len
invariant acc(sig.len) && acc(sig.u64Data)
{
sig.u64Data := sig.u64Data[h0 := U64.max()]
h0 := h0 + 1
}
} else {
var h: Int := 0
while (h < self.ranker_num_hash_functions)
invariant 0 <= h && h <= self.ranker_num_hash_functions
invariant sig.len == self.ranker_num_hash_functions
invariant acc(sig.len) && acc(sig.u64Data)
{
var min_hash: Int := U64.max()
var seed_a: Int := self.ranker_lsh_hash_params.u64Data[h * 2]
var seed_b: Int := self.ranker_lsh_hash_params.u64Data[h * 2 + 1]
var i: Int := 0
while (i < tokens.len)
invariant 0 <= i && i <= tokens.len
{
var token: Int := tokens.u32Data[i]
var hv: Int := U64.xor(stableHash(bytesOfU32Seq(Seq(token)), seed_a), seed_b)
if (U64.lt(hv, min_hash)) {
min_hash := hv
}
i := i + 1
}
sig.u64Data := sig.u64Data[h := min_hash]
h := h + 1
}
}
fold ArrayU64(sig)
fold ArrayU64(self.ranker_lsh_hash_params)
fold ArrayU32Read(tokens)
fold Ranker(self)
}

method Ranker_jaccardSimilarityFromSignatures(sig1: Ref, sig2: Ref) returns (sim: F32)
requires ArrayU64Read(sig1)
requires ArrayU64Read(sig2)
ensures true
{
unfold ArrayU64Read(sig1)
unfold ArrayU64Read(sig2)
if (sig1.len != sig2.len) {
sim := F32.zero()
} else if (sig1.len == 0) {
sim := F32.zero()
} else {
var matches: Int := 0
var i: Int := 0
while (i < sig1.len)
invariant 0 <= i && i <= sig1.len
invariant matches >= 0
{
if (sig1.u64Data[i] == sig2.u64Data[i]) {
matches := matches + 1
}
i := i + 1
}
sim := F32.div(F32.fromInt(matches), F32.fromInt(sig1.len))
}
fold ArrayU64Read(sig2)
fold ArrayU64Read(sig1)
}

method Ranker_estimateJaccard(set1: Ref, set2: Ref) returns (est: F32)
requires BitSet(set1)
requires BitSet(set2)
ensures true
{
unfold BitSet(set1)
unfold BitSet(set2)
unfold ArrayU64Read(set1.bitset_bits)
unfold ArrayU64Read(set2.bitset_bits)
var intersect: Int := 0
var union_count: Int := 0
var words: Int := minInt(set1.bitset_bits.len, set2.bitset_bits.len)
var i: Int := 0
while (i < words)
invariant 0 <= i && i <= words
invariant intersect >= 0 && union_count >= 0
{
var a: Int := set1.bitset_bits.u64Data[i]
var b: Int := set2.bitset_bits.u64Data[i]
intersect := intersect + U64.popCount(U64.xor(U64.xor(a, b), U64.xor(a, a)))
union_count := union_count + U64.popCount(U64.xor(U64.xor(a, a), U64.xor(a, b)))
i := i + 1
}
if (union_count == 0) {
est := F32.zero()
} else {
est := F32.div(F32.fromInt(intersect), F32.fromInt(union_count))
}
fold ArrayU64Read(set2.bitset_bits)
fold ArrayU64Read(set1.bitset_bits)
fold BitSet(set2)
fold BitSet(set1)
}

method Ranker_vectorScore(embedding: Ref, query_emb: Ref) returns (score: F32)
requires Tensor(embedding)
requires Tensor(query_emb)
requires memEqlSeqInt(embedding.tensor_shape.usizeData, query_emb.tensor_shape.usizeData)
ensures true
{
unfold Tensor(embedding)
unfold Tensor(query_emb)
unfold ArrayUSizeRead(embedding.tensor_shape)
unfold ArrayUSizeRead(query_emb.tensor_shape)
unfold ArrayF32Read(embedding.tensor_data)
unfold ArrayF32Read(query_emb.tensor_data)

if (embedding.tensor_data.len == 0) {
score := F32.zero()
} else {
var dot: F32 := F32.zero()
var norm_e: F32 := F32.zero()
var norm_q: F32 := F32.zero()
var len: Int := embedding.tensor_data.len
var i: Int := 0
while (i < len)
invariant 0 <= i && i <= len
{
var e: F32 := embedding.tensor_data.f32Data[i]
var q: F32 := query_emb.tensor_data.f32Data[i]
if (!F32.isNan(e) && !F32.isNan(q) && !F32.isInf(e) && !F32.isInf(q)) {
dot := F32.add(dot, F32.mul(e, q))
norm_e := F32.add(norm_e, F32.mul(e, e))
norm_q := F32.add(norm_q, F32.mul(q, q))
}
i := i + 1
}
if (F32.le(norm_e, F32.zero()) || F32.le(norm_q, F32.zero())) {
score := F32.zero()
} else {
var ne: F32 := F32.sqrt(norm_e)
var nq: F32 := F32.sqrt(norm_q)
if (ne == F32.zero() || nq == F32.zero()) {
score := F32.zero()
} else {
var denom: F32 := F32.mul(ne, nq)
var res: F32 := F32.div(dot, denom)
score := F32.clamp(res, F32.minusOne(), F32.one())
}
}
}

fold ArrayF32Read(query_emb.tensor_data)
fold ArrayF32Read(embedding.tensor_data)
fold ArrayUSizeRead(query_emb.tensor_shape)
fold ArrayUSizeRead(embedding.tensor_shape)
fold Tensor(query_emb)
fold Tensor(embedding)
}

