method Ranker_weightedAverage(scores: Ref, weights: Ref) returns (avg: F32)
requires ArrayF32Read(scores)
requires ArrayF32Read(weights)
requires scores.len == weights.len
ensures true
{
unfold ArrayF32Read(scores)
unfold ArrayF32Read(weights)
if (scores.len == 0) {
avg := F32.zero()
} else {
var num: F32 := F32.zero()
var den: F32 := F32.zero()
var i: Int := 0
while (i < scores.len)
invariant 0 <= i && i <= scores.len
{
var s: F32 := scores.f32Data[i]
var w: F32 := weights.f32Data[i]
if (!F32.isNan(s) && !F32.isNan(w) && !F32.isInf(s) && !F32.isInf(w)) {
num := F32.add(num, F32.mul(s, w))
den := F32.add(den, w)
}
i := i + 1
}
if (den == F32.zero()) {
avg := F32.zero()
} else {
avg := F32.div(num, den)
}
}
fold ArrayF32Read(weights)
fold ArrayF32Read(scores)
}

method Ranker_exponentialDecay(scores: Ref, decay_factor: F32)
requires ArrayF32(scores)
ensures ArrayF32(scores)
{
unfold ArrayF32(scores)
if (scores.len == 0) {
} else {
if (F32.le(decay_factor, F32.zero()) || F32.le(F32.one(), decay_factor)) {
} else {
var current: F32 := F32.one()
var i: Int := 0
while (i < scores.len)
invariant 0 <= i && i <= scores.len
invariant acc(scores.len) && acc(scores.f32Data)
{
var v: F32 := scores.f32Data[i]
if (!F32.isNan(v) && !F32.isInf(v)) {
scores.f32Data := scores.f32Data[i := F32.mul(v, current)]
}
current := F32.mul(current, decay_factor)
i := i + 1
}
}
}
fold ArrayF32(scores)
}

method Ranker_normalizeScoresStatic(scores: Ref)
requires ArrayF32(scores)
ensures ArrayF32(scores)
{
unfold ArrayF32(scores)
if (scores.len == 0) {
} else {
var minS: F32 := F32.posInf()
var maxS: F32 := F32.negInf()
var valid: Int := 0
var i: Int := 0
while (i < scores.len)
invariant 0 <= i && i <= scores.len
invariant valid >= 0
invariant acc(scores.len) && acc(scores.f32Data)
{
var s: F32 := scores.f32Data[i]
if (!F32.isNan(s) && !F32.isInf(s)) {
valid := valid + 1
if (F32.lt(s, minS)) { minS := s }
if (F32.lt(maxS, s)) { maxS := s }
}
i := i + 1
}
if (valid == 0) {
} else {
if (maxS == minS) {
i := 0
while (i < scores.len)
invariant 0 <= i && i <= scores.len
invariant acc(scores.len) && acc(scores.f32Data)
{
var s2: F32 := scores.f32Data[i]
if (!F32.isNan(s2) && !F32.isInf(s2)) {
scores.f32Data := scores.f32Data[i := F32.fromReal(0.5)]
}
i := i + 1
}
} else {
var range: F32 := F32.sub(maxS, minS)
i := 0
while (i < scores.len)
invariant 0 <= i && i <= scores.len
invariant acc(scores.len) && acc(scores.f32Data)
{
var s3: F32 := scores.f32Data[i]
if (!F32.isNan(s3) && !F32.isInf(s3)) {
var norm: F32 := F32.div(F32.sub(s3, minS), range)
scores.f32Data := scores.f32Data[i := norm]
}
i := i + 1
}
}
}
}
fold ArrayF32(scores)
}

method Ranker_normalizeScores(self: Ref, scores: Ref)
requires Ranker(self)
requires ArrayF32(scores)
ensures ArrayF32(scores)
{
call Ranker_normalizeScoresStatic(scores)
}

method Ranker_updateWeights(self: Ref, gradients: Ref)
requires Ranker(self)
requires ArrayF32Read(gradients)
ensures Ranker(self)
{
unfold Ranker(self)
unfold ArrayF32(self.ranker_ngram_weights)
unfold ArrayF32Read(gradients)
var i: Int := 0
var lim: Int := minInt(self.ranker_ngram_weights.len, gradients.len)
while (i < lim)
invariant 0 <= i && i <= lim
invariant lim == minInt(self.ranker_ngram_weights.len, gradients.len)
invariant acc(self.ranker_ngram_weights.len) && acc(self.ranker_ngram_weights.f32Data)
{
var g: F32 := gradients.f32Data[i]
if (!F32.isNan(g) && !F32.isInf(g)) {
var upd: F32 := F32.add(self.ranker_ngram_weights.f32Data[i], F32.mul(g, RankerConfig_LEARNING_RATE()))
upd := F32.clamp(upd, F32.zero(), F32.one())
self.ranker_ngram_weights.f32Data := self.ranker_ngram_weights.f32Data[i := upd]
}
i := i + 1
}
fold ArrayF32Read(gradients)
fold ArrayF32(self.ranker_ngram_weights)
fold Ranker(self)
}

