method Ranker_topKHeap(self: Ref, ssi: Ref, query: Ref, k: Int, a: Ref) returns (topk: Ref)
requires Ranker(self)
requires SSI(ssi)
requires Allocator(a)
requires ArrayU32Read(query)
requires k >= 0
ensures ArrayRef(topk)
ensures topk.len <= k
ensures forall i: Int :: 0 <= i && i < topk.len ==> RankedSegment(topk.refData[i])
{
if (k == 0) {
call topk := allocRef(a, 0)
} else {
var cands: Ref
call cands := SSI_retrieveTopK(ssi, query, RankerConfig_DEFAULT_TOP_K_RETRIEVAL(), a)
unfold ArrayRef(cands)
var outN: Int := minInt(k, cands.len)
call topk := allocRef(a, outN)
unfold ArrayRef(topk)
var i: Int := 0
while (i < outN)
invariant 0 <= i && i <= outN
invariant topk.len == outN
invariant acc(topk.len) && acc(topk.refData)
{
var src: Ref := cands.refData[i]
unfold RankedSegment(src)
var sc: F32
call sc := Ranker_scoreSequenceWithQuery(self, src.ranked_tokens, query, ssi)
var rs: Ref
call rs := RankedSegment_init(a, src.ranked_tokens, sc, src.ranked_position, src.ranked_anchor)
fold RankedSegment(src)
topk.refData := topk.refData[i := rs]
i := i + 1
}
i := 0
while (i < cands.len)
invariant 0 <= i && i <= cands.len
{
call RankedSegment_deinit(a, cands.refData[i])
i := i + 1
}
fold ArrayRef(topk)
fold ArrayRef(cands)
call freeRef(a, cands)
}
}

method Ranker_rankByMultipleCriteria(self: Ref, candidates: Ref, criteria: Ref, weights: Ref, a: Ref)
requires Ranker(self)
requires Allocator(a)
requires ArrayRef(candidates)
requires forall i: Int :: 0 <= i && i < candidates.len ==> RankedSegment(candidates.refData[i])
requires ArrayRefRead(criteria)
requires forall j: Int :: 0 <= j && j < criteria.len ==> ArrayF32Read(criteria.refData[j])
requires ArrayF32Read(weights)
ensures ArrayRef(candidates)
ensures forall i: Int :: 0 <= i && i < candidates.len ==> RankedSegment(candidates.refData[i])
{
unfold ArrayRef(candidates)
if (candidates.len == 0) {
fold ArrayRef(candidates)
} else {
unfold ArrayRefRead(criteria)
unfold ArrayF32Read(weights)
if (criteria.len == 0 || weights.len == 0) {
fold ArrayF32Read(weights)
fold ArrayRefRead(criteria)
fold ArrayRef(candidates)
} else {
var num_cand: Int := candidates.len
var num_crit: Int := minInt(criteria.len, weights.len)
var combined: Ref
call combined := allocF32(a, num_cand)
unfold ArrayF32(combined)
var c: Int := 0
while (c < num_cand)
invariant 0 <= c && c <= num_cand
invariant combined.len == num_cand
invariant acc(combined.len) && acc(combined.f32Data)
{
var crit_score: F32 := F32.zero()
var cr: Int := 0
while (cr < num_crit)
invariant 0 <= cr && cr <= num_crit
{
var arr: Ref := criteria.refData[cr]
unfold ArrayF32Read(arr)
if (c < arr.len) {
var sv: F32 := arr.f32Data[c]
var wv: F32 := weights.f32Data[cr]
if (!F32.isNan(sv) && !F32.isNan(wv) && !F32.isInf(sv) && !F32.isInf(wv)) {
crit_score := F32.add(crit_score, F32.mul(sv, wv))
}
}
fold ArrayF32Read(arr)
cr := cr + 1
}
combined.f32Data := combined.f32Data[c := crit_score]
c := c + 1
}
fold ArrayF32(combined)
call Ranker_normalizeScoresStatic(combined)
call freeF32(a, combined)
fold ArrayF32Read(weights)
fold ArrayRefRead(criteria)
fold ArrayRef(candidates)
}
}
}

