call gradients := allocF32(self.ranker_allocator, self.ranker_ngram_weights.len)
unfold ArrayF32(gradients)
var epoch: Int := 0
while (epoch < epochs)
invariant 0 <= epoch && epoch <= epochs
invariant ArrayF32(gradients)
{
unfold ArrayF32(gradients)
var g: Int := 0
while (g < gradients.len)
invariant 0 <= g && g <= gradients.len
invariant acc(gradients.len) && acc(gradients.f32Data)
{
gradients.f32Data := gradients.f32Data[g := F32.zero()]
