method Ranker_parallelScore(self: Ref, sequences: Ref, ssi: Ref, num_threads: Int) returns (scores: Ref)
requires Ranker(self)
requires SSI(ssi)
requires ArrayRefRead(sequences)
requires forall i: Int :: 0 <= i && i < sequences.len ==> ArrayU32Read(sequences.refData[i])
ensures ArrayF32(scores)
