}

method Ranker_calibrateWeights(self: Ref, training_data: Ref, labels: Ref, ssi: Ref, epochs: Int)
requires Ranker(self)
requires SSI(ssi)
requires ArrayRefRead(training_data)
requires forall i: Int :: 0 <= i && i < training_data.len ==> ArrayU32Read(training_data.refData[i])
requires ArrayF32Read(labels)
requires training_data.len == labels.len
requires epochs >= 0
ensures Ranker(self)
{
unfold Ranker(self)
if (training_data.len == 0 || labels.len == 0) {
fold Ranker(self)
} else {
var gradients: Ref
call gradients := allocF32(self.ranker_allocator, self.ranker_ngram_weights.len)
unfold ArrayF32(gradients)
var epoch: Int := 0
while (epoch < epochs)
invariant 0 <= epoch && epoch <= epochs
invariant ArrayF32(gradients)
{
unfold ArrayF32(gradients)
var g: Int := 0
while (g < gradients.len)
invariant 0 <= g && g <= gradients.len
invariant acc(gradients.len) && acc(gradients.f32Data)
{
gradients.f32Data := gradients.f32Data[g := F32.zero()]
g := g + 1
}
fold ArrayF32(gradients)

  var i: Int := 0
  while (i < training_data.len)
    invariant 0 <= i && i <= training_data.len
  {
    var seq: Ref := training_data.refData[i]
    var pred: F32
    call pred := Ranker_scoreSequence(self, seq, ssi)
    var label: F32 := labels.f32Data[i]
    if (!F32.isNan(pred) && !F32.isNan(label) && !F32.isInf(pred) && !F32.isInf(label)) {
      var err: F32 := F32.sub(pred, label)
      unfold ArrayF32(gradients)
      g := 0
      while (g < gradients.len)
        invariant 0 <= g && g <= gradients.len
        invariant acc(gradients.len) && acc(gradients.f32Data)
      {
        var upd: F32 := F32.add(gradients.f32Data[g], F32.mul(err, RankerConfig_LEARNING_RATE()))
        gradients.f32Data := gradients.f32Data[g := upd]
        g := g + 1
      }
      fold ArrayF32(gradients)
    }
    i := i + 1
  }
  call Ranker_updateWeights(self, gradients)
  epoch := epoch + 1
}
call freeF32(self.ranker_allocator, gradients)
fold Ranker(self)

}
}

